INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('95b1090e-117c-4fd8-95ab-7b18071641cd', 'a1b2c3d4-0001-4000-8000-000000000001', 1, 'O Amor de Deus por Você', 'Descobrindo que somos amados', '{"bible_ref": "Jo 3,16", "reflection": "Deus nos amou primeiro. Medite sobre o que significa ser amado incondicionalmente."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;